import { defineConfig } from "oxfmt";
import ultracite from "ultracite/oxfmt";

// Owned elsewhere: course skills (upstream), CHANGELOG.md (written by
// semantic-release) and infra/sdks (generated by `pulumi package add`).
const owned = [".claude/skills/**", "CHANGELOG.md", "infra/sdks/**"];

export default defineConfig({
  ...ultracite,
  ignorePatterns: [...(ultracite.ignorePatterns ?? []), ...owned],
});
